async function precioEnPesos(dolares) {
  const respuesta = await fetch("https://dolarapi.com/v1/dolares/blue");
  const dolar = await respuesta.json();
  console.log("Dólar blue, venta:", dolar.venta);
  return dolares * dolar.venta;
}

console.log("Pidiendo la cotización...");
precioEnPesos(20).then(pesos => {
  console.log(`La campera de $20 USD sale $${pesos} pesos`);
});
